<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>RideFixer Shop - E-Bike Parts Coming Soon</title>
<link rel="icon" href="https://ridefixer.app/my-android-app/android/app/src/main/res/mipmap-xxxhdpi/ic_launcher.png" type="image/png" />
<link rel="apple-touch-icon" href="https://ridefixer.app/my-android-app/android/app/src/main/res/mipmap-xxxhdpi/ic_launcher.png" />
<meta name="theme-color" content="#06101d" />
<script>try{const s=localStorage.getItem('ridefixer-shop-theme');const p=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';document.documentElement.setAttribute('data-theme',s||p)}catch(e){document.documentElement.setAttribute('data-theme','dark')}</script>
<style>:root{--bg:#06101d;--bg2:#081827;--card:rgba(255,255,255,.08);--card2:rgba(255,255,255,.12);--text:#f8fbff;--muted:#a9b8ca;--line:rgba(255,255,255,.14);--brand:#00d4ff;--green:#22c7a9;--ghost:rgba(255,255,255,.08)}html[data-theme='light']{--bg:#f7fbff;--bg2:#edf4fa;--card:#fff;--card2:#fff;--text:#0b1724;--muted:#334155;--line:rgba(8,24,39,.14);--ghost:rgba(8,24,39,.05)}body{background:linear-gradient(180deg,var(--bg),var(--bg2));color:var(--text);font-family:Inter,system-ui;margin:0}.brand img{width:44px;height:44px;border-radius:14px}.nav a,.pill,.btn-ghost,.item,.mini div,h1,h2,h3{color:var(--text)}.sub{color:var(--muted)}html[data-theme='light'] .gradient{background:linear-gradient(135deg,#0369a1,#111827,#0f766e);-webkit-background-clip:text;-webkit-text-fill-color:transparent}</style>
</head>
<body></body>
</html>